const OpenXmlPartDescriptor& SlidePart::Descriptor() noexcept
{
    return GeneratedPartsHelper::kSlidePartDescriptor;
}

std::shared_ptr<ExyokiOffice::DocumentFormat::OpenXml::Presentation::Slide> SlidePart::GetSlide() const
{
    return GetTypedRootElement();
}

std::shared_ptr<ExyokiOffice::DocumentFormat::OpenXml::Presentation::Slide> SlidePart::GetTypedRootElement() const
{
    auto root = GetRootElement();
    if (!root)
    {
        return nullptr;
    }
    return openxmlelement_cast<ExyokiOffice::DocumentFormat::OpenXml::Presentation::Slide>(root);
}

